while k<states.len(){let s=states[k];let r=rank(s);let(mut a,mut b,mut d,mut ss,mut st,mut s6)=(0,0,0,0,0,0);let mut dest=vec![];
 for q in 0..30{let x=join(s,&kernels[0][q]);let y=join(s,&kernels[1][q]);let z=join(x,&kernels[1][q]);s6+=rank(join(s,&kernels[2][q]))-r;a+=rank(x)-r;b+=rank(y)-r;d+=rank(z)-r;for t in [x,y,z]{let next=if let Some(id)=ids.get(&t){*id}else{let id=states.len();states.push(t);ids.insert(t,id);id};dest.push(next)}for u in 0..30{ss+=rank(join(x,&kernels[0][u]))-r;st+=rank(join(x,&kernels[1][u]))-r;}}
 assert!(states.len()<=1988);rows.push(json!({"basis":s,"rank":r,"destinations":dest,"source6_one_numerator":s6,"source_one_numerator":a,"twist_one_numerator":b,"dual_same_query_numerator":d,"two_iid_source_numerator":ss,"iid_source_then_twist_numerator":st,"dual_beats_two_iid_source":30*d>ss,"one_denominator":30,"two_denominator":900}));k+=1;
}
